/* Explore is a self-contained, synthetic market scenario, not a live feed. */
icons.explore='<circle cx="12" cy="12" r="9"/><path d="m16 8-2.5 5.5L8 16l2.5-5.5z"/>';
const exploreState={day:26,topic:'Breakfast'};
const exploreDays=Array.from({length:30},(_,i)=>{const day=i+1,dow=new Date(2026,8,day).getDay(),weekend=dow===0||dow===6,event=day===26;const score=event?92:weekend?70+(day%3)*5:35+(day*7%24);const low=event?460:weekend?440:390,high=event?590:weekend?570:510;return {day,weekend,event,score,low,high,rate:520};});
const exploreSelected=()=>exploreDays[exploreState.day-1];
const exploreDate=d=>new Date(2026,8,d).toLocaleDateString(lang==='en'?'en-US':'zh-CN',{month:'short',day:'numeric'});
const exploreSignal=d=>d.score>=70?tr('Higher demand than usual','需求高于平常'):d.score>=48?tr('Typical demand','需求处于常态'):tr('Quieter than usual','需求低于平常');
const exploreTopics={Location:{zh:'位置',n:26,tone:['Guests love the setting','客人喜欢这里的位置'],comments:[['A peaceful street, with cafés a short walk away.','街道安静，步行就能到咖啡馆。'],['Easy to find, but the last bus is quite early.','位置好找，不过末班车有点早。']]},Cleanliness:{zh:'清洁',n:24,tone:['Consistently positive','评价持续正面'],comments:[['Fresh linens and a spotless room.','床品清爽，房间非常干净。'],['The bathroom felt well cared for.','浴室维护得很好。']]},Breakfast:{zh:'早餐',n:18,tone:['Mostly positive','大多为正面评价'],comments:[['Loved the warm breakfast before our morning walk.','晨间散步前的热早餐很贴心。'],['Fresh and simple. A little more variety would be lovely.','新鲜简单，如果种类再多一点就更好了。'],['The later breakfast time made our stay more relaxed.','早餐供应时间晚一些，让住宿更从容。']]},Service:{zh:'服务',n:21,tone:['Warm, personal service','温暖而贴心的服务'],comments:[['The host shared thoughtful local tips.','房东提供了贴心的当地游玩建议。'],['A quick, helpful reply when we arrived late.','我们晚到时，房东回复迅速并提供帮助。']]}};
function renderExplore(){document.getElementById('app').innerHTML=`<div class="explore-page"><header class="explore-top"><span class="sample-label">${tr('EXPLORE','探索')}</span><button id="explore-language">${tr('中文','EN')}</button></header><div class="explore-hero"><span class="explore-kicker">${tr('A LITTLE LOCAL PERSPECTIVE','换个角度，看周边')}</span><h1>${tr('Explore what’s happening around you.','发现身边，正在发生的变化。')}</h1><p class="explore-disclaimer">${tr('A fictional neighbourhood · September 2026','虚构周边市场 · 2026 年 9 月')}<br>${tr('Sample signals, rates & reviews. No live connections.','需求、房价与评价均为示例，未连接实时平台。')}</p></div>
<section class="pulse-section" aria-labelledby="pulse-title"><div class="explore-section-head"><h2 id="pulse-title">${tr('Market pulse','市场脉动')}</h2><span class="pulse-dot" aria-hidden="true"></span></div><p class="pulse-headline">${tr('Demand appears to be rising this weekend.','这个周末，需求似乎正在升温。')}</p><div class="pulse-canvas" id="pulse-canvas"><svg id="pulse-svg" viewBox="0 0 360 190" aria-label="${tr('Sample demand across September. Use the date controls below to explore.','9 月示例需求，请使用下方日期控件探索。')}" role="img"></svg></div><div class="pulse-readout" aria-live="polite"><strong id="pulse-date"></strong><span id="pulse-signal"></span></div><div class="pulse-controls"><button id="pulse-prev" aria-label="${tr('Previous date','前一天')}">${svg('left')}</button><label class="visually-hidden" for="pulse-range">${tr('Explore September dates','探索 9 月日期')}</label><input id="pulse-range" type="range" min="1" max="30" value="${exploreState.day}"><button id="pulse-next" aria-label="${tr('Next date','后一天')}">${svg('right')}</button></div><div class="pulse-axis"><span>SEP 01</span><span>${tr('Drag or tap to explore','拖动或点选日期')}</span><span>SEP 30</span></div></section>
<section class="demand-section"><div class="explore-section-head"><h2>${tr('Demand calendar','需求日历')}</h2><span>${tr('September 2026','2026 年 9 月')}</span></div><div class="heat-week">${tr('M T W T F S S','一 二 三 四 五 六 日').split(' ').map(x=>`<span>${x}</span>`).join('')}</div><div class="heat-grid"><span></span>${exploreDays.map(d=>`<button data-market-day="${d.day}" class="heat-day level-${d.score>=70?3:d.score>=48?2:1}" aria-label="${exploreDate(d.day)} · ${exploreSignal(d)}${d.event?tr(' · Nearby event (sample)',' · 周边活动（示例）'):''}" aria-pressed="${d.day===exploreState.day}"><span>${d.day}</span>${d.event?'<i aria-hidden="true"></i>':''}</button>`).join('')}</div><div class="heat-legend"><span>${tr('Quieter','较低')}</span><i></i><i></i><i></i><span>${tr('Higher','较高')}</span><span class="event-key">• ${tr('Sample event','示例活动')}</span></div></section>
<section class="price-section" id="price-section"><div class="explore-section-head"><h2>${tr('Where your rate sits','你的房价位置')}</h2><label><span class="visually-hidden">${tr('Rate comparison date','房价比较日期')}</span><select id="price-date">${exploreDays.map(d=>`<option value="${d.day}">${exploreDate(d.day)}</option>`).join('')}</select></label></div><p class="price-value">${tr('Your rate','你的房价')} <strong>¥520</strong><span>${tr('/ night','/ 晚')}</span></p><div class="price-spectrum"><div class="market-band"></div><span class="rate-marker" id="rate-marker"><i></i><b>${tr('You','你')}</b></span></div><div class="spectrum-labels"><span>${tr('Lower','较低')}</span><span>${tr('Market','市场')}</span><span>${tr('Higher','较高')}</span></div><p id="market-range" class="market-range"></p><p class="explore-note">${tr('Illustrative comparable stays · Same date, per night. Rates stay unchanged.','虚构同类住宿 · 同一天每晚房价，不会修改定价。')}</p></section>
<section class="guest-section"><span class="explore-kicker">${tr('GUEST INTELLIGENCE','客人洞察')}</span><h2>${tr('What guests are talking about','客人都在聊什么')}</h2><p class="explore-note">${tr('Tap a topic from 42 fictional reviews. Topics can overlap.','点选 42 条虚构评价中的话题，同一评价可涉及多个话题。')}</p><div class="topic-orbit" role="group" aria-label="${tr('Review topics','评价话题')}">${Object.entries(exploreTopics).map(([key,t],i)=>`<button class="topic topic-${i}" data-topic="${key}" aria-pressed="${key===exploreState.topic}"><span>${tr(key,t.zh)}</span><small>${t.n}</small></button>`).join('')}</div><div class="topic-detail" aria-live="polite"><div><span id="topic-name"></span><h3 id="topic-tone"></h3><p id="topic-count"></p></div><button id="topic-comments">${tr('View comments','查看评价')} ${svg('arrow')}</button></div></section>
<section class="nearby-section"><div class="explore-section-head"><h2>${tr('A look around','看看附近住宿')}</h2><div class="stay-controls"><button id="stay-prev" aria-label="${tr('Previous stay','上一家住宿')}">${svg('left')}</button><button id="stay-next" aria-label="${tr('Next stay','下一家住宿')}">${svg('right')}</button></div></div><p class="explore-note">${tr('Fictional comparable stays · Selected date','虚构同类住宿 · 当前所选日期')} <span id="stay-date"></span></p><div class="stay-carousel" id="stay-carousel" tabindex="0" aria-label="${tr('Swipe through nearby stays','左右滑动浏览附近住宿')}">${['You','Nearby Stay A','Nearby Stay B'].map((name,i)=>`<article class="stay-slide"><div class="stay-art art-${i}" role="img" aria-label="${tr('Illustration of a fictional stay','虚构住宿示意图')}"><span class="stay-sun"></span><div class="stay-building"><i></i><i></i><i></i><i></i></div><span class="stay-tree"></span><span class="art-caption">${tr('ILLUSTRATION','示意图')}</span></div><div class="stay-info"><h3>${tr(name,['你的民宿','附近住宿 A','附近住宿 B'][i])}</h3><strong id="stay-rate-${i}"></strong></div><p>${tr(['Your sample property','Courtyard stay · Similar size','Garden stay · Similar amenities'][i],['你的示例民宿','庭院住宿 · 规模相似','花园住宿 · 设施相似'][i])}</p></article>`).join('')}</div><p class="explore-note">${tr('Compare context, not just price. No real properties or OTA reviews are shown.','结合环境理解价格。此处没有真实房源或 OTA 评价。')}</p></section><footer class="explore-footer">${tr('DISCOVER → COMPARE → UNDERSTAND','发现 → 比较 → 理解')}</footer></div>`;
document.getElementById('explore-language').onclick=()=>{lang=lang==='en'?'zh':'en';render()};
document.getElementById('pulse-range').oninput=e=>setExploreDay(+e.target.value);document.getElementById('pulse-prev').onclick=()=>setExploreDay(Math.max(1,exploreState.day-1));document.getElementById('pulse-next').onclick=()=>setExploreDay(Math.min(30,exploreState.day+1));document.getElementById('price-date').onchange=e=>setExploreDay(+e.target.value);
document.querySelectorAll('[data-market-day]').forEach(b=>b.onclick=()=>{setExploreDay(+b.dataset.marketDay);exploreSheet('day')});document.querySelectorAll('[data-topic]').forEach(b=>b.onclick=()=>{exploreState.topic=b.dataset.topic;updateExploreTopic()});document.getElementById('topic-comments').onclick=()=>exploreSheet('comments');
const canvas=document.getElementById('pulse-canvas');function scrub(e){const r=canvas.getBoundingClientRect();setExploreDay(Math.max(1,Math.min(30,Math.round((e.clientX-r.left)/r.width*29)+1)))}canvas.onpointerdown=e=>{canvas.setPointerCapture(e.pointerId);scrub(e)};canvas.onpointermove=e=>{if(canvas.hasPointerCapture(e.pointerId))scrub(e)};canvas.onpointerup=e=>{if(canvas.hasPointerCapture(e.pointerId))canvas.releasePointerCapture(e.pointerId)};
const carousel=document.getElementById('stay-carousel');let stayIndex=0;function scrollStay(n){stayIndex=Math.max(0,Math.min(2,n));carousel.children[stayIndex].scrollIntoView({behavior:motion()?'smooth':'instant',block:'nearest',inline:'start'})}document.getElementById('stay-prev').onclick=()=>scrollStay(stayIndex-1);document.getElementById('stay-next').onclick=()=>scrollStay(stayIndex+1);carousel.onscroll=()=>{stayIndex=Math.round(carousel.scrollLeft/(carousel.firstElementChild.getBoundingClientRect().width+14))};carousel.onkeydown=e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();scrollStay(stayIndex+(e.key==='ArrowRight'?1:-1))}};
setExploreDay(exploreState.day);updateExploreTopic();}
function setExploreDay(day){exploreState.day=day;const d=exploreSelected();document.getElementById('pulse-range').value=day;document.getElementById('pulse-range').setAttribute('aria-valuetext',exploreDate(day)+' · '+exploreSignal(d));document.getElementById('pulse-prev').disabled=day===1;document.getElementById('pulse-next').disabled=day===30;document.getElementById('pulse-date').textContent=exploreDate(day);document.getElementById('pulse-signal').textContent=exploreSignal(d);document.getElementById('price-date').value=day;document.querySelectorAll('[data-market-day]').forEach(b=>b.setAttribute('aria-pressed',+b.dataset.marketDay===day));const points=exploreDays.map((x,i)=>[8+i*344/29,168-x.score*1.36]);let path=`M${points[0].join(',')}`;for(let i=1;i<points.length;i++){const a=points[i-1],b=points[i],mid=(a[0]+b[0])/2;path+=` C${mid},${a[1]} ${mid},${b[1]} ${b.join(',')}`}const [x,y]=points[day-1];document.getElementById('pulse-svg').innerHTML=`<defs><linearGradient id="pulse-fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#7eaac6" stop-opacity=".5"/><stop offset="1" stop-color="#dcecf5" stop-opacity=".05"/></linearGradient></defs><path d="${path} L352,188 L8,188Z" fill="url(#pulse-fill)" stroke="none"/><path class="pulse-line" d="${path}" fill="none" stroke="#608da9" stroke-width="2"/><line x1="${x}" y1="${y}" x2="${x}" y2="188" stroke="#608da9" stroke-width="1" stroke-dasharray="3 5"/><circle cx="${x}" cy="${y}" r="10" fill="#ffffff66" stroke="none"/><circle cx="${x}" cy="${y}" r="4" fill="#fff" stroke="#608da9" stroke-width="2"/>`;
const position=Math.max(5,Math.min(95,25+(d.rate-d.low)/(d.high-d.low)*50));document.getElementById('rate-marker').style.left=position+'%';document.getElementById('market-range').textContent=tr(`Sample market range ¥${d.low}–¥${d.high}`,`示例市场范围 ¥${d.low}–¥${d.high}`);document.getElementById('stay-date').textContent=exploreDate(day);[520,d.low+30,d.high-30].forEach((rate,i)=>document.getElementById('stay-rate-'+i).textContent='¥'+rate);}
function updateExploreTopic(){const key=exploreState.topic,t=exploreTopics[key];document.querySelectorAll('[data-topic]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.topic===key));document.getElementById('topic-name').textContent=tr(key,t.zh);document.getElementById('topic-tone').textContent=tx(t.tone);document.getElementById('topic-count').textContent=tr(`Mentioned in ${t.n} sample reviews`,`${t.n} 条示例评价提及`);}
function exploreSheet(type){const d=exploreSelected(),t=exploreTopics[exploreState.topic];sheet.innerHTML=`<div class="sheet-close-row"><span class="sample-label">${tr('EXPLORE · SAMPLE DATA','探索 · 示例数据')}</span><button class="round" id="explore-close" aria-label="${tr('Close','关闭')}">×</button></div><h2 id="activity-title">${type==='comments'?tr(exploreState.topic,t.zh):exploreDate(d.day)}</h2><div id="explore-sheet-content"></div>`;sheet.querySelector('#explore-close').onclick=()=>sheet.close();const body=sheet.querySelector('#explore-sheet-content');if(type==='comments'){body.innerHTML=`<p>${tx(t.tone)} · ${tr('Fictional review excerpts','虚构评价摘录')}</p>${t.comments.map((c,i)=>`<blockquote class="demo-review"><p>“${tx(c)}”</p><cite>${tr('Sample guest','示例客人')} ${i+1} · ${tr('Illustrative only','仅作演示')}</cite></blockquote>`).join('')}`;}else{body.innerHTML=`<p class="market-day-signal">${exploreSignal(d)}</p><div class="day-context"><span>${d.weekend?tr('Weekend','周末'):tr('Weekday','工作日')}</span>${d.event?`<span>${tr('Nearby event · Sample','周边活动 · 示例')}</span>`:''}</div><p>${d.event?tr('A fictional neighbourhood arts weekend is included in this scenario. It is not a verified event or forecast.','此情境设定了虚构的周边艺术周末，并非已核实活动或预测。'):tr('This date is part of a synthetic demand pattern, not a live market reading.','该日期属于模拟需求情境，并非实时市场监测。')}</p><button class="confirm-task" id="see-opportunity">${tr('See opportunity','看看机会')} ${svg('arrow')}</button>`;body.querySelector('#see-opportunity').onclick=()=>{sheet.querySelector('h2').textContent=tr('Give guests a reason to stay.','给客人一个留下来的理由。');body.innerHTML=`<p>${tr(`For ${exploreDate(d.day)}, try a short local-stay story. Confirm availability and verify any event details before using them.`,`围绕 ${exploreDate(d.day)} 起草一段本地住宿故事。使用前请核对空房与活动信息。`)}</p><p class="explore-note">${tr('No suggested discount. No automatic price changes or publishing.','不预设折扣，不自动调价或发布。')}</p><button class="confirm-task" id="compare-date">${tr('Compare this date','比较这一天')} ${svg('arrow')}</button><button class="explore-draft-link" id="explore-draft">${tr('Open promotion draft in Work','在工作区打开推广草稿')} ${svg('arrow')}</button>`;body.querySelector('#compare-date').onclick=()=>{sheet.close();document.getElementById('price-section').scrollIntoView({behavior:motion()?'smooth':'instant',block:'center'})};body.querySelector('#explore-draft').onclick=()=>{sheet.close();if(workState.confirmed.includes('promotion'))showActivity('confirmed-promotion');else location.hash='work/promotion'};};}sheet.showModal();}
render();
